options(bdynets.basemap.auto=FALSE)
library(bdynets)
inside<-function(n)if(exists(n,mode='function'))get(n,mode='function') else getFromNamespace(n,'bdynets')
fail<-function(e)inherits(tryCatch(force(e),error=identity),'error')
r<-data.frame(road_id=c('a','b'));r$geometry<-list(rbind(c(10,50),c(10.01,50)),rbind(c(10.01,50),c(10,50)))
f<-data.frame(road_id=rep(c('a','b'),3),time=rep(c(0,60,180),each=2),flow=c(10,20,12,NA,8,16))
x<-traffic_data(r,f,times=c(0,60,180),interval_seconds=c(60,120,60),unit='vehicles/hour')
tr<-traffic_trend(x);stopifnot(inherits(tr,'traffic_trend'),inherits(tr,'data.frame'),identical(tr$mean,c(15,12,12)))
out<-tempfile();dir.create(out)
grDevices::png(file.path(out,'trend.png'));plot(tr,index=2,ylab='Custom mean');grDevices::dev.off()
original<-serialize(x,NULL);v<-inside('.tm_view')(x,'change');stopifnot(identical(original,serialize(x,NULL)));stopifnot(all(is.na(v$values[1,])),identical(as.numeric(v$values[2,]),c(2,NA_real_)),identical(as.numeric(v$values[3,]),c(-4,NA_real_)),identical(v$unit,x$unit),v$scale$kind=='change',identical(x$values,matrix(c(10,12,8,20,NA,16),3)))
rule<-list(definition='Toy test condition',interval_meaning='Each toy frame describes its full supplied interval',unit='minutes',missing_policy='break',scale=list(kind='log1p'))
fixed<-inside('.tm_view')(x,'change',reference=1);stopifnot(identical(as.numeric(fixed$values[3,]),c(-2,-4)))
stopifnot(is.na(traffic_summary(x,1,mode='change')$mean),traffic_summary(x,2,mode='change')$mean==2,
 identical(traffic_trend(x,mode='change')$mean,c(NA_real_,2,-4)))
d<-inside('.tm_view')(x,'duration',threshold=10,comparison='>=',duration_rule=rule);stopifnot(identical(as.numeric(d$values[,1]),c(1,3,0)),identical(as.numeric(d$values[,2]),c(1,NA_real_,1)),d$unit=='minutes')
d2<-inside('.tm_view')(x,'duration',threshold=10,comparison='>',duration_rule=rule);stopifnot(identical(as.numeric(d2$values[,1]),c(0,2,0)))
gap<-traffic_data(r,f,times=c(0,60,180),interval_seconds=60)
stopifnot(is.na(inside('.tm_view')(gap,'change')$values[3,1]),inside('.tm_view')(gap,'duration',threshold=5,comparison='>=',duration_rule=rule)$values[3,1]==1)
implicit<-traffic_data(r,f,times=c(0,60,180))
stopifnot(fail(inside('.tm_view')(implicit,'duration',threshold=10)),fail(inside('.tm_view')(x,'duration')),fail(inside('.tm_view')(x,'change',reference=9)),fail(inside('.tm_view')(x,'duration',threshold=10,comparison='==')))
only_events<-traffic_data(events=data.frame(time=0,lon=10,lat=50),times=0,interval_seconds=60)
grDevices::png(file.path(out,'events.png'));plot(traffic_trend(only_events));grDevices::dev.off()
stopifnot(fail(inside('.tm_view')(only_events,'change')))
traffic_map(x,file.path(out,'change.html'),mode='change')
traffic_report(x,file.path(out,'duration.html'),index=2,mode='duration',threshold=10,comparison='>=',duration_rule=rule)
h<-paste(readLines(file.path(out,'duration.html')),collapse='\n');stopifnot(grepl('mode = &quot;duration&quot;',h,fixed=TRUE))
traffic_export(x,file.path(out,'change'),index=3,mode='change',reference=1)
sel<-readRDS(file.path(out,'change','selected-frame.rds'))
stopifnot(sel$measurement$mode=='change',identical(sel$flow$flow,c(-2,-4)),identical(sel$source_flow$flow,c(8,16)),identical(sel$reference_flow$flow,c(10,20)),identical(sel$unit,x$unit))
one<-traffic_data(r,data.frame(road_id=c('a','b'),time=0,flow=c(0,0)),times=0,interval_seconds=60)
grDevices::png(file.path(out,'one.png'));plot(traffic_trend(one));grDevices::dev.off()
stopifnot(inside('.tm_view')(one,'change',reference=1)$scale$kind=='change',fail(traffic_data(r,transform(f,flow=-1))))
stopifnot(fail(plot(tr,metric='bad')),fail(plot(tr,index=0)))
unlink(out,recursive=TRUE)
cat('Generic trends, aligned changes, explicit threshold-run durations, units, missing/gapped intervals, derived HTML/exports and source preservation passed.\n')
